import { Component, inject, OnInit, OnDestroy, signal } from '@angular/core';
import { DOCUMENT } from '@angular/common';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators, AbstractControl, ValidationErrors } from '@angular/forms';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { AuthService } from '../../services/auth.service';
import { ThemeService } from '../../services/theme.service';
import { InstitutionalBarComponent } from '../../components/institutional-bar/institutional-bar.component';
import { MainNavbarComponent } from '../../components/main-navbar/main-navbar.component';
import { FooterSectionComponent } from '../../components/footer-section/footer-section.component';

@Component({
  selector: 'app-reset-password',
  imports: [
    CommonModule,
    ReactiveFormsModule,
    RouterLink,
    InstitutionalBarComponent,
    MainNavbarComponent,
    FooterSectionComponent,
  ],
  templateUrl: './reset-password.component.html',
  styleUrl: './reset-password.component.scss',
})
export class ResetPasswordComponent implements OnInit, OnDestroy {
  private readonly themeService = inject(ThemeService);
  private readonly document = inject(DOCUMENT);
  private readonly fb = inject(FormBuilder);
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly authService = inject(AuthService);

  resetForm!: FormGroup;
  code = '';
  email = '';

  readonly isLoading = signal<boolean>(false);
  readonly errorMessage = signal<string | null>(null);
  readonly successMessage = signal<string | null>(null);
  showPassword = signal<boolean>(false);

  ngOnInit() {
    this.code = this.route.snapshot.queryParams['code'] || '';
    this.document.documentElement.setAttribute('data-bs-theme', 'light');
    this.email = this.route.snapshot.queryParams['email'] || this.route.snapshot.queryParams['amp;email'] || '';

    this.resetForm = this.fb.group({
      code: [this.code || '', [Validators.required, Validators.pattern(/^\d{6}$/)]],
      password: ['', [Validators.required, Validators.minLength(8)]],
      confirmPassword: ['', [Validators.required]],
    }, { validators: this.passwordMatchValidator });
  }

  ngOnDestroy(): void {
    this.themeService.refreshTheme();
  }

  private passwordMatchValidator(control: AbstractControl): ValidationErrors | null {
    const password = control.get('password');
    const confirmPassword = control.get('confirmPassword');
    
    if (password && confirmPassword && password.value !== confirmPassword.value) {
      confirmPassword.setErrors({ passwordMismatch: true });
      return { passwordMismatch: true };
    }
    
    return null;
  }

  togglePasswordVisibility() {
    this.showPassword.update((val) => !val);
  }

  onSubmit() {
    if (this.resetForm.invalid) return;

    this.isLoading.set(true);
    this.errorMessage.set(null);
    this.successMessage.set(null);

    const { code, password, confirmPassword } = this.resetForm.value;

    this.authService.resetPassword(code, this.email, password, confirmPassword).subscribe({
      next: (res) => {
        this.isLoading.set(false);
        this.successMessage.set(res.message || 'Contraseña restablecida con éxito.');
        setTimeout(() => {
          this.router.navigate(['/login']).then(() => {
            this.authService.openModal();
          });
        }, 3000);
      },
      error: (err) => {
        this.isLoading.set(false);
        if (err.status === 422 && err.error?.errors) {
          const errors = err.error.errors;
          const firstErrorKey = Object.keys(errors)[0];
          this.errorMessage.set(errors[firstErrorKey][0]);
        } else {
          this.errorMessage.set('No se pudo restablecer la contraseña. Solicita un nuevo código.');
        }
      },
    });
  }
}
